(() => {
  'use strict';
  const canvas = document.getElementById('world');
  const ctx = canvas.getContext('2d');
  const $ = (s) => document.querySelector(s);
  const state = {
    grade:120, wood:1, metal:1, cloth:1, food:2, carParts:0, day:1, discoveries:0,
    player:{x:6,y:6}, recruits:[], buildings:[], searched:[], completed:[], accepted:[], hired:{},
    carFixed:false, buildMode:false, zoom:1, worldOffset:{x:0,y:0}, lastTick:Date.now(),
    name:'The Landing', muted:false
  };
  const resources=['wood','metal','cloth','food','carParts'];
  const labels={wood:'Reclaimed wood',metal:'Scrap metal',cloth:'Fabric',food:'Rations',carParts:'Flight parts'};
  const locations=[
    {id:'home',name:'Your plot',kind:'home',x:2,y:7,desc:'A patch of open land with a good view of the old city.'},
    {id:'market',name:'Corner Exchange',kind:'shop',x:8,y:2,desc:'A little trading post tucked beneath the elevated tramline.',person:{id:'jun',name:'Jun Park',role:'Trader & tinkerer',note:'Found sheltering between the shelves.'}},
    {id:'diner',name:'Starlight Diner',kind:'diner',x:4,y:3,desc:'A chrome-fronted diner. The neon still flickers after all these years.',person:{id:'mae',name:'Mae Torres',role:'Cook & community builder',note:'Keeping the old coffee machine company.'}},
    {id:'mill',name:'Windmill Service Shed',kind:'mill',x:10,y:5,desc:'A maintenance shed beside a quiet wind turbine. Something useful may be inside.'},
    {id:'garage',name:'Cloudline Garage',kind:'garage',x:11,y:7,desc:'A hangar full of grounded sky-cars and half-finished repairs.'},
    {id:'greenhouse',name:'Glasshouse No. 8',kind:'greenhouse',x:6,y:8,desc:'A sunken greenhouse. It is warm, quiet, and not quite empty.',person:{id:'imani',name:'Imani Okafor',role:'Grower & botanist',note:'Tending the last living plants in the district.'}},
    {id:'relay',name:'Old Relay Station',kind:'relay',x:2,y:2,desc:'A radio mast catches a clean signal from somewhere beyond the ridge.'},
    {id:'crate',name:'Supply crate',kind:'crate',x:7,y:5,desc:'An intact field box, sealed against the dust.'},
    {id:'junkyard',name:'The Quiet Mile',kind:'junkyard',x:12,y:3,desc:'A stretch of abandoned cars. The best parts are never on the first one.'}
  ];
  const placeById=(id)=>locations.find(p=>p.id===id);
  const key=(x,y)=>`${x},${y}`;
  let W=0,H=0,dpr=1,tileW=60,tileH=32,toastTimer;

  function save(){try{localStorage.setItem('afterlight-save',JSON.stringify(state));}catch(e){}}
  function load(){try{const data=JSON.parse(localStorage.getItem('afterlight-save'));if(data){Object.assign(state,data);state.buildMode=false;state.lastTick=Date.now();}}catch(e){}}
  function resize(){const r=canvas.getBoundingClientRect();dpr=Math.min(window.devicePixelRatio||1,2);W=r.width;H=r.height;canvas.width=Math.round(W*dpr);canvas.height=Math.round(H*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);tileW=Math.min(W/13.7,H/8.4)*state.zoom;tileH=tileW*.52;draw();}
  function point(x,y){return {x:W*.5+(x-y)*tileW*.5+state.worldOffset.x,y:H*.39+(x+y)*tileH*.5+state.worldOffset.y};}
  function tilePoly(p){ctx.beginPath();ctx.moveTo(p.x,p.y-tileH*.5);ctx.lineTo(p.x+tileW*.5,p.y);ctx.lineTo(p.x,p.y+tileH*.5);ctx.lineTo(p.x-tileW*.5,p.y);ctx.closePath();}
  function fillTile(p,color,stroke='#cfdbca'){tilePoly(p);ctx.fillStyle=color;ctx.fill();ctx.strokeStyle=stroke;ctx.lineWidth=.8;ctx.stroke();}
  function seeded(n){const x=Math.sin(n*127.1+311.7)*43758.5453;return x-Math.floor(x);}
  function drawTree(p,size=1){ctx.save();ctx.translate(p.x,p.y);ctx.fillStyle='#779079';ctx.beginPath();ctx.ellipse(1,7*size,9*size,4*size,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#6b826e';ctx.beginPath();ctx.moveTo(0,-17*size);ctx.lineTo(-8*size,-1*size);ctx.lineTo(9*size,-1*size);ctx.closePath();ctx.fill();ctx.fillStyle='#829983';ctx.beginPath();ctx.moveTo(0,-12*size);ctx.lineTo(-6*size,-2*size);ctx.lineTo(6*size,-2*size);ctx.closePath();ctx.fill();ctx.fillStyle='#8c765f';ctx.fillRect(-1.5*size,-1*size,3*size,7*size);ctx.restore();}
  function drawBuilding(x,y,kind,scale=1){const p=point(x,y);const s=scale;ctx.save();ctx.translate(p.x,p.y);
    // soft footprint and roof side
    ctx.fillStyle='#54675a22';ctx.beginPath();ctx.ellipse(0,7*s,25*s,9*s,0,0,Math.PI*2);ctx.fill();
    const palette={home:['#c9b89a','#8f9e83','#eadfc9'],shop:['#d9b78c','#8c6954','#f2d794'],diner:['#b9c9bd','#718d82','#e9836a'],mill:['#c5c6a9','#87916c','#e4dda6'],garage:['#9ca8a2','#687a74','#d2a866'],greenhouse:['#afc6af','#718b78','#b8e4d1'],relay:['#c8c0a3','#847d62','#e6ce86'],crate:['#be9c6e','#89694a','#e3c184'],junkyard:['#afaaa0','#797c72','#c5a77a'],building:['#c5c4ad','#7e8e7f','#d3c7a6']};
    const c=palette[kind]||palette.building;
    ctx.fillStyle=c[1];ctx.beginPath();ctx.moveTo(-20*s,-3*s);ctx.lineTo(0,5*s);ctx.lineTo(20*s,-3*s);ctx.lineTo(20*s,-18*s);ctx.lineTo(0,-10*s);ctx.lineTo(-20*s,-18*s);ctx.closePath();ctx.fill();
    ctx.fillStyle=c[0];ctx.beginPath();ctx.moveTo(-20*s,-18*s);ctx.lineTo(0,-27*s);ctx.lineTo(20*s,-18*s);ctx.lineTo(0,-10*s);ctx.closePath();ctx.fill();
    ctx.fillStyle=c[2];ctx.fillRect(-5*s,-17*s,7*s,9*s);ctx.fillStyle='#48564c';ctx.fillRect(7*s,-17*s,5*s,5*s);
    if(kind==='diner'){ctx.fillStyle='#f8b48c';ctx.fillRect(-15*s,-24*s,30*s,3*s);ctx.fillStyle='#567364';ctx.font=`${5*s}px monospace`;ctx.textAlign='center';ctx.fillText('DINER',0,-21*s);}
    if(kind==='shop'){ctx.fillStyle='#e7d6a5';ctx.fillRect(-14*s,-25*s,28*s,4*s);ctx.fillStyle='#667863';ctx.font=`${5*s}px monospace`;ctx.textAlign='center';ctx.fillText('TRADE',0,-22*s);}
    if(kind==='greenhouse'){ctx.strokeStyle='#e0f0d7';ctx.lineWidth=2*s;ctx.beginPath();ctx.moveTo(-14*s,-19*s);ctx.lineTo(0,-25*s);ctx.lineTo(14*s,-19*s);ctx.stroke();}
    if(kind==='relay'){ctx.strokeStyle='#65766c';ctx.lineWidth=1.5*s;ctx.beginPath();ctx.moveTo(0,-24*s);ctx.lineTo(0,-49*s);ctx.moveTo(-5*s,-38*s);ctx.lineTo(5*s,-38*s);ctx.moveTo(-4*s,-45*s);ctx.lineTo(4*s,-45*s);ctx.stroke();ctx.fillStyle='#dca36e';ctx.beginPath();ctx.arc(0,-49*s,2*s,0,Math.PI*2);ctx.fill();}
    if(kind==='mill'){ctx.fillStyle='#aab89b';ctx.beginPath();ctx.arc(11*s,-27*s,7*s,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#76866e';ctx.lineWidth=1.5*s;for(let i=0;i<4;i++){const a=i*Math.PI/2;ctx.beginPath();ctx.moveTo(11*s,-27*s);ctx.lineTo(11*s+Math.cos(a)*7*s,-27*s+Math.sin(a)*7*s);ctx.stroke();}}
    if(kind==='garage'){ctx.fillStyle='#5e716b';ctx.fillRect(-13*s,-20*s,12*s,11*s);ctx.fillStyle='#d8b576';ctx.fillRect(-11*s,-17*s,8*s,4*s);}
    if(kind==='home'){ctx.fillStyle='#759277';ctx.fillRect(-16*s,-20*s,32*s,4*s);ctx.fillStyle='#fbf1d8';ctx.font=`${5*s}px monospace`;ctx.textAlign='center';ctx.fillText('YOUR LAND',0,-17*s);}
    ctx.restore();return p;
  }
  function drawCrate(p){ctx.save();ctx.translate(p.x,p.y);ctx.fillStyle='#927950';ctx.fillRect(-7,-8,14,9);ctx.fillStyle='#c2a876';ctx.beginPath();ctx.moveTo(-8,-8);ctx.lineTo(0,-13);ctx.lineTo(8,-8);ctx.lineTo(0,-4);ctx.closePath();ctx.fill();ctx.strokeStyle='#e0c999';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(0,-12);ctx.lineTo(0,-5);ctx.stroke();ctx.restore();}
  function drawSurvivor(p,color='#c78367',isPlayer=false){ctx.save();ctx.translate(p.x,p.y);ctx.fillStyle='#263a3027';ctx.beginPath();ctx.ellipse(0,3,7,3,0,0,Math.PI*2);ctx.fill();ctx.fillStyle=isPlayer?'#526f62':color;ctx.beginPath();ctx.ellipse(0,-3,5,7,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#e7c8a9';ctx.beginPath();ctx.arc(0,-12,4,0,Math.PI*2);ctx.fill();ctx.fillStyle=isPlayer?'#31473d':'#4b4338';ctx.beginPath();ctx.arc(0,-13,4,Math.PI,Math.PI*2);ctx.fill();if(isPlayer){ctx.strokeStyle='#f1d38f';ctx.lineWidth=1.5;ctx.beginPath();ctx.arc(0,-8,8,Math.PI,Math.PI*2);ctx.stroke();}ctx.restore();}
  function drawHover(p,label,color='#f5f5ec'){ctx.save();ctx.font='8px "DM Mono", monospace';const w=ctx.measureText(label).width+14;ctx.fillStyle='#23352de8';ctx.beginPath();ctx.roundRect(p.x-w/2,p.y-52,w,18,5);ctx.fill();ctx.fillStyle=color;ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(label,p.x,p.y-43);ctx.restore();}

