function drawHover(p,label,color='#f5f5ec'){ctx.save();ctx.font='8px "DM Mono", monospace';const w=ctx.measureText(label).width+14;ctx.fillStyle='#23352de8';ctx.beginPath();ctx.roundRect(p.x-w/2,p.y-52,w,18,5);ctx.fill();ctx.fillStyle=color;ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(label,p.x,p.y-43);ctx.restore();}
function draw(){if(!W||!H)return;ctx.clearRect(0,0,W,H);const bg=ctx.createLinearGradient(0,0,0,H);bg.addColorStop(0,'#dfe8dc');bg.addColorStop(1,'#cbd9ca');ctx.fillStyle=bg;ctx.fillRect(0,0,W,H);
  // distant canopy and stream
  ctx.fillStyle='#adc4ad';ctx.beginPath();ctx.ellipse(W*.1,H*.15,W*.23,H*.15,-.2,0,Math.PI*2);ctx.fill();ctx.fillStyle='#c2d2bd';ctx.beginPath();ctx.ellipse(W*.9,H*.2,W*.25,H*.17,.3,0,Math.PI*2);ctx.fill();
  const buildings=new Map(locations.filter(o=>o.kind!=='crate').map(o=>[key(o.x,o.y),o]));
  for(let d=0;d<23;d++){for(let x=0;x<14;x++){const y=d-x;if(y<0||y>=10)continue;const p=point(x,y);const n=seeded(x*31+y*73);const tint=['#d8e2d2','#d5e0d1','#d2ddce','#dbe4d7'][Math.floor(n*4)];fillTile(p,tint);
    if(n>.76&&!buildings.has(key(x,y))&&!(x===state.player.x&&y===state.player.y)){ctx.fillStyle=n>.9?'#b4c29d':'#c3d0b4';ctx.beginPath();ctx.ellipse(p.x+tileW*.12,p.y,5,2,0,0,Math.PI*2);ctx.fill();}
  }}
  // stream winding behind the neighborhood
  ctx.save();ctx.strokeStyle='#a5c5c1';ctx.globalAlpha=.48;ctx.lineWidth=7;ctx.beginPath();for(let i=0;i<8;i++){const p=point(i+3,1+Math.floor(i*.75));if(!i)ctx.moveTo(p.x,p.y);else ctx.lineTo(p.x,p.y);}ctx.stroke();ctx.restore();
  for(let d=0;d<23;d++){for(let x=0;x<14;x++){const y=d-x;if(y<0||y>=10)continue;const p=point(x,y);const o=buildings.get(key(x,y));if(o){drawBuilding(x,y,o.kind==='crate'?'crate':o.kind,1);if(o.kind==='crate')drawCrate(p);}else if(seeded(x*31+y*73)>.89){drawTree(p,.78+seeded(x*19+y*13)*.45);}}}
  state.buildings.forEach((b,i)=>{const p=point(b.x,b.y);drawBuilding(b.x,b.y,b.kind==='shop'?'shop':b.kind==='garden'?'greenhouse':'home',.9);if(b.kind==='shop'&&state.hired[b.id])drawHover(p,`WORKER: ${state.hired[b.id]}`,'#dce9d5');});
  // a parked sky-car at the garage
  const gp=point(11,7);ctx.save();ctx.translate(gp.x+16,gp.y-5);ctx.fillStyle='#354a43';ctx.beginPath();ctx.ellipse(0,0,13,5,0,0,Math.PI*2);ctx.fill();ctx.fillStyle=state.carFixed?'#a7c7ae':'#9a9b88';ctx.beginPath();ctx.moveTo(-11,-1);ctx.lineTo(-5,-7);ctx.lineTo(5,-7);ctx.lineTo(12,-1);ctx.closePath();ctx.fill();ctx.fillStyle='#d9e8d9';ctx.fillRect(-3,-6,5,3);ctx.fillStyle=state.carFixed?'#f0d892':'#b67e63';ctx.beginPath();ctx.arc(0,-11,2,0,Math.PI*2);ctx.fill();ctx.restore();
  locations.filter(o=>o.person&&!state.recruits.some(r=>r.id===o.person.id)).forEach(o=>{const p=point(o.x,o.y);drawSurvivor(p,o.id==='diner'?'#bc7a77':'#ca9569');});
  const pp=point(state.player.x,state.player.y);drawSurvivor(pp,'#557666',true);if(state.buildMode){ctx.save();ctx.fillStyle='#496b5140';ctx.strokeStyle='#547855';ctx.setLineDash([4,3]);tilePoly(pp);ctx.fill();ctx.stroke();ctx.restore();}
  const owned=state.buildings.map(b=>key(b.x,b.y));for(const b of state.buildings){const p=point(b.x,b.y);ctx.fillStyle='#587553';ctx.beginPath();ctx.arc(p.x+tileW*.33,p.y-3,3,0,Math.PI*2);ctx.fill();}
  requestAnimationFrame(()=>{});
}
function syncUI(){ $('#gradeTop').textContent=state.grade;$('#settlerCount').textContent=1+state.recruits.length;$('#peopleCount').textContent=state.recruits.length;$('#buildingCount').textContent=state.buildings.length;$('#settlementMeter').style.width=`${Math.min(100,22+state.buildings.length*16+state.recruits.length*9)}%`;
  $('#discoveriesLabel').textContent=`${state.discoveries} / 8 DISCOVERIES`;const gathered=resources.reduce((n,r)=>n+Math.min(state[r],r==='carParts'?3:1),0);$('#milestoneProgress').style.width=`${Math.min(100,20+gathered*16)}%`;$('#milestoneLabel').textContent=`${Math.min(5,gathered)} of 5 supplies gathered`;
  $('#missionCount').textContent=Math.max(0,2-state.completed.length);$('#dayLabel').textContent=`DAY ${String(state.day).padStart(2,'0')}`;$('#weatherLabel').textContent=state.day%3===0?'SOFT RAIN':'CLEAR SKIES';save();draw();
}
function toast(message,icon='✳'){const node=document.createElement('div');node.className='toast';node.innerHTML=`<span>${icon}</span>${message}`;$('#toastStack').append(node);setTimeout(()=>node.remove(),3200);}
function mapToast(message){const el=$('#mapToast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2100);}
function openModal(html){$('#modalContent').innerHTML=html;$('#modalBackdrop').classList.add('open');$('#modalBackdrop').setAttribute('aria-hidden','false');}
function closeModal(){$('#modalBackdrop').classList.remove('open');$('#modalBackdrop').setAttribute('aria-hidden','true');state.buildMode=false;draw();}
function changeResource(name,amount){state[name]=Math.max(0,(state[name]||0)+amount);}
function costText(cost){return Object.entries(cost).map(([k,v])=>`${v} ${k==='grade'?'Grade':labels[k]}`).join(' · ');}
function canPay(cost){return Object.entries(cost).every(([k,v])=>state[k]>=v);}
function pay(cost){Object.entries(cost).forEach(([k,v])=>state[k]-=v);}
function actionButton(label,action,disabled=false){return `<button data-do="${action}" ${disabled?'disabled':''}>${label}</button>`;}
function openPlace(o){
  if(o.person&&!state.recruits.some(r=>r.id===o.person.id))return openPerson(o);
  if(o.id==='home'){openModal(`<div class="modal-kicker">YOUR PIECE OF THE FRONTIER</div><h2>The Landing</h2><p class="modal-lead">A little open land, all yours. Build anywhere in the neighborhood—your home doesn't have to stay here.</p><div class="inventory-grid">${inventoryItems()}</div><div class="build-hint">Tip: gather materials from supply crates and buildings, or trade Grade at the Corner Exchange. Build mode lets you choose any open tile.</div><button class="modal-action" data-do="build">OPEN BUILD MENU ↗</button>`);return;}
  if(o.kind==='crate'||o.kind==='mill'||o.kind==='junkyard')return openSalvage(o);
  if(o.kind==='shop')return openExchange(o);
  if(o.kind==='diner')return openDiner(o);
  if(o.kind==='garage')return openGarage(o);
  if(o.kind==='greenhouse')return openGreenhouse(o);
  if(o.kind==='relay')return openRelay(o);
}
function inventoryItems(){return resources.map(r=>`<div class="inventory-item"><span>${state[r]}</span><b>${labels[r].toUpperCase()}</b><small>in your pack</small></div>`).join('');}
function openPerson(o){const p=o.person;openModal(`<div class="modal-kicker">A NEW FACE IN NEW EDEN</div><h2>Meet ${p.name}</h2><p class="modal-lead">${p.note} ${p.name.split(' ')[0]} has been making do alone. There's room for one more in your settlement.</p><div class="person-row"><span class="person-avatar">${p.name[0]}</span><div><b>${p.name}</b><small>${p.role}</small></div><span class="person-status">AVAILABLE</span></div><div class="build-hint">Survivors can join your settlement and work at any shop you build. No one is left behind.</div>${actionButton('INVITE TO YOUR SETTLEMENT','recruit-'+p.id)}`);}
function openSalvage(o){const searched=state.searched.includes(o.id);const loot=o.id==='crate'?{wood:2,metal:1,food:1}:o.id==='mill'?{metal:2,cloth:1,carParts:1}:{metal:1,wood:1,carParts:1};const reward=Object.entries(loot).map(([k,v])=>`${v} ${labels[k]}`).join(', ');
  openModal(`<div class="modal-kicker">FIELD NOTES · ${o.id==='crate'?'SUPPLY FIND':o.id==='mill'?'SERVICE SHED':'SALVAGE YARD'}</div><h2>${o.name}</h2><p class="modal-lead">${o.desc}</p><div class="option-card"><div class="option-symbol">${o.id==='crate'?'▣':'⌕'}</div><div class="option-copy"><b>${searched?'Picked clean':'Search the area'}</b><p>${searched?'You already checked here. Leave a little for the next person.':`You might find ${reward}.`}</p></div><div class="option-meta">${searched?'DONE':'FREE'}</div></div>${actionButton(searched?'NOTHING LEFT HERE':'SEARCH FOR SUPPLIES','search-'+o.id,searched)}<div class="modal-note">The neighborhood has ${locations.filter(l=>['crate','mill','junkyard'].includes(l.id)).length} salvage spots. Supplies replenish each new day.</div>`);
}
function openExchange(){const goods=[['wood','Reclaimed wood',18],['metal','Scrap metal',22],['cloth','Fabric',14],['food','Rations',10],['carParts','Flight part',38]];openModal(`<div class="modal-kicker">CORNER EXCHANGE · PLAYER-RUN COMMERCE</div><h2>Trade what you have.</h2><p class="modal-lead">Jun keeps the old shelves stocked. Grade is the common currency out here. You have <b>${state.grade} Grade</b>.</p><div class="modal-list">${goods.map(([id,n,cost])=>`<div class="option-card"><span class="option-symbol">${id==='carParts'?'✦':'＋'}</span><div class="option-copy"><b>${n}</b><p>One unit · ${cost} Grade</p></div><button data-do="buy-${id}" ${state.grade<cost?'disabled':''}>BUY</button></div>`).join('')}</div><div class="modal-note">Sell extra salvage for Grade: ${actionButton('SELL 1 WOOD · +8 GRADE','sell-wood')} ${actionButton('SELL 1 METAL · +10 GRADE','sell-metal')}</div>`);}
function openDiner(o){openModal(`<div class="modal-kicker">STARLIGHT DINER · COMMUNITY</div><h2>A familiar kind of welcome.</h2><p class="modal-lead">${o.desc} The kitchen is quiet but the coffee smells almost right.</p><div class="option-card"><span class="option-symbol">☕</span><div class="option-copy"><b>Share a meal</b><p>Spend one ration to recover your energy and get to know the neighborhood.</p></div><div class="option-meta">1 RATION</div></div>${actionButton('SHARE A MEAL','meal',state.food<1)}<div class="modal-note">Once you have a shop, your settlers can work there. Build a diner or market anywhere you like.</div>`);}
function openGarage(){const needed=3;openModal(`<div class="modal-kicker">CLOUDLINE GARAGE · OLD SKY-CAR</div><h2>${state.carFixed?'Your car is flight-ready.':'A little work, then the sky.'}</h2><p class="modal-lead">The old car still floats on its repulsors, but its lift coils are cracked. Find parts in the open world or trade for them.</p><div class="option-card"><span class="option-symbol">✦</span><div class="option-copy"><b>${state.carFixed?'Coils repaired':'Lift-coil assembly'}</b><p>${state.carFixed?'Your sky-car is repaired and ready to fly.':'Needs 3 flight parts · You have '+state.carParts}</p></div><div class="option-meta">${state.carFixed?'READY':`${Math.min(3,state.carParts)}/3`}</div></div>${state.carFixed?'<div class="modal-note">Your car is ready to fly. The horizon is wide open.</div>':actionButton('REPAIR THE SKY-CAR','repair-car',state.carParts<needed)}${actionButton('TAKE A DELIVERY MISSION · +40 GRADE','car-mission',state.completed.includes('delivery'))}`);}
function openGreenhouse(o){openModal(`<div class="modal-kicker">GLASSHOUSE NO. 8 · GROW SOMETHING</div><h2>A small green corner.</h2><p class="modal-lead">${o.desc} Imani has kept these beds alive through every season.</p><div class="option-card"><span class="option-symbol">❋</span><div class="option-copy"><b>Gather a few cuttings</b><p>Take food for your journey. The plants will grow back.</p></div><div class="option-meta">FREE</div></div>${actionButton('GATHER 2 RATIONS','gather-food',state.completed.includes('garden-gather'))}<div class="modal-note">A garden or greenhouse is a useful first shop: build one anywhere and assign a survivor to tend it.</div>`);}
function openRelay(){openModal(`<div class="modal-kicker">OLD RELAY STATION · COMMUNITY SIGNAL</div><h2>Someone is out there.</h2><p class="modal-lead">A voice crackles through the static. A family on the north road needs a hand moving their things to safety.</p><div class="option-card"><span class="option-symbol">⌁</span><div class="option-copy"><b>North Road welcome wagon</b><p>Bring 2 wood and 1 food to help a new family settle in.</p></div><div class="option-meta">+55 G</div></div>${actionButton(state.completed.includes('welcome')?'MISSION COMPLETE':'ACCEPT & COMPLETE','welcome-mission',state.completed.includes('welcome')||!canPay({wood:2,food:1}))}<div class="modal-note">Missions are a good way to earn Grade and help people along the way. No fighting—just neighbors looking out for each other.</div>`);}

