function openRelay(){openModal(`<div class="modal-kicker">OLD RELAY STATION · COMMUNITY SIGNAL</div><h2>Someone is out there.</h2><p class="modal-lead">A voice crackles through the static. A family on the north road needs a hand moving their things to safety.</p><div class="option-card"><span class="option-symbol">⌁</span><div class="option-copy"><b>North Road welcome wagon</b><p>Bring 2 wood and 1 food to help a new family settle in.</p></div><div class="option-meta">+55 G</div></div>${actionButton(state.completed.includes('welcome')?'MISSION COMPLETE':'ACCEPT & COMPLETE','welcome-mission',state.completed.includes('welcome')||!canPay({wood:2,food:1}))}<div class="modal-note">Missions are a good way to earn Grade and help people along the way. No fighting—just neighbors looking out for each other.</div>`);}
const buildOptions=[
  {id:'shelter',name:'Starter shelter',icon:'⌂',desc:'A warm, dry place to rest. A home base for your settlement.',cost:{wood:3,cloth:1,grade:12}},
  {id:'shop',name:'Corner shop',icon:'▤',desc:'A place to trade. Assign any survivor to run the counter.',cost:{wood:4,metal:2,grade:25}},
  {id:'diner',name:'Neighborhood diner',icon:'☕',desc:'Serve meals and give people a reason to gather.',cost:{wood:3,metal:2,grade:20}},
  {id:'garden',name:'Community garden',icon:'❋',desc:'Grow food and make a little green space.',cost:{wood:2,cloth:1,grade:15}}
];
function openBuild(){state.buildMode=false;openModal(`<div class="modal-kicker">MAKE THE NEIGHBORHOOD YOURS</div><h2>Build anywhere.</h2><p class="modal-lead">Choose what to build, then tap any open tile on the map. Every structure is made from things you can find or trade for.</p><div class="modal-list">${buildOptions.map(o=>`<div class="option-card"><span class="option-symbol">${o.icon}</span><div class="option-copy"><b>${o.name}</b><p>${o.desc}</p><small class="option-meta">${costText(o.cost)}</small></div>${actionButton('PLACE',`choose-${o.id}`,!canPay(o.cost))}</div>`).join('')}</div><div class="build-hint">Open tiles only; place things anywhere on the map. Recruit survivors and assign them to your shops.</div>`);}
function openJobs(){const shops=state.buildings.filter(b=>['shop','diner','garden'].includes(b.kind));if(!shops.length){openModal(`<div class="modal-kicker">A DAY'S WORK</div><h2>Jobs start at home.</h2><p class="modal-lead">Work a shift at a settlement shop or take a delivery mission. Build your first shop to open more jobs.</p><div class="option-card"><span class="option-symbol">✧</span><div class="option-copy"><b>Neighborhood errands</b><p>Help carry supplies between the diner and the Exchange.</p></div><div class="option-meta">+18 G</div></div>${actionButton(state.completed.includes('errands')?'SHIFT COMPLETE':'WORK A SHIFT','errands',state.completed.includes('errands'))}<div class="modal-note">Build a shop anywhere, invite a survivor to your settlement, and you can assign them to work there.</div>`);return;}
  openModal(`<div class="modal-kicker">SETTLEMENT JOB BOARD</div><h2>A good day's work.</h2><p class="modal-lead">Pick up a shift at a local business. You'll earn Grade and keep the neighborhood humming.</p>${shops.map((b,i)=>`<div class="job-slot"><span class="option-symbol">${b.kind==='garden'?'❋':b.kind==='diner'?'☕':'▤'}</span><div><b>${b.label}</b><small>${state.hired[b.id]?`Run by ${state.hired[b.id]}`:'Could use a hand today'}</small></div>${actionButton('WORK · +20 G','shift-'+b.id,state.completed.includes('shift-'+b.id))}</div>`).join('')}<div class="modal-note">Your workers generate a little Grade for the settlement over time, too.</div>`);
}
function openPeople(){openModal(`<div class="modal-kicker">NEW EDEN · YOUR PEOPLE</div><h2>Nobody rebuilds alone.</h2><p class="modal-lead">You've found ${state.recruits.length} survivor${state.recruits.length===1?'':'s'}. Any of them can work in a shop you build.</p>${state.recruits.length?state.recruits.map(p=>`<div class="person-row"><span class="person-avatar">${p.name[0]}</span><div><b>${p.name}</b><small>${p.role}</small></div><span class="person-status">${Object.values(state.hired).includes(p.name)?'AT WORK':'SETTLED'}</span></div>`).join(''):'<div class="modal-note">Survivors are tucked into everyday places: shops, restaurants, and the buildings you search for supplies. Jun is waiting at the Corner Exchange; Mae is at the Starlight Diner.</div>'}<div class="build-hint">Assign a survivor to any shop: open its building panel on the map and choose a worker.</div>${actionButton('OPEN BUILD MENU','build')}`);}
function openMissions(){openModal(`<div class="modal-kicker">MUTUAL AID · MISSION BOARD</div><h2>Ways to lend a hand.</h2><p class="modal-lead">No monsters, no rush. Just people finding their feet and helping each other along the way.</p><div class="option-card"><span class="option-symbol">⌁</span><div class="option-copy"><b>North Road welcome wagon</b><p>At the Relay Station · Bring 2 wood and 1 food · Reward 55 Grade</p></div>${actionButton(state.completed.includes('welcome')?'DONE':'GO','go-relay',state.completed.includes('welcome'))}</div><div class="option-card"><span class="option-symbol">✦</span><div class="option-copy"><b>Cloudline parts delivery</b><p>At the garage · Help restore a grounded sky-car · Reward 40 Grade</p></div>${actionButton(state.completed.includes('delivery')?'DONE':'GO','go-garage',state.completed.includes('delivery'))}</div><div class="option-card"><span class="option-symbol">☕</span><div class="option-copy"><b>Neighborhood errands</b><p>Carry things between the diner and Exchange · Reward 18 Grade</p></div>${actionButton(state.completed.includes('errands')?'DONE':'WORK','errands',state.completed.includes('errands'))}</div><div class="modal-note">Your missions live in the neighborhood. Tap GO to find the place and see what needs doing.</div>`);}
function visitLocation(id){const o=placeById(id);if(!o)return;const p=point(o.x,o.y);state.worldOffset.x+=W*.5-p.x;state.worldOffset.y+=H*.48-p.y;state.player={x:o.x,y:o.y};draw();setTimeout(()=>openPlace(o),140);}

