  function visitLocation(id){const o=placeById(id);if(!o)return;const p=point(o.x,o.y);state.worldOffset.x+=W*.5-p.x;state.worldOffset.y+=H*.48-p.y;state.player={x:o.x,y:o.y};draw();setTimeout(()=>openPlace(o),140);}
  function openBuilt(b){const job=state.recruits.find(p=>!Object.values(state.hired).includes(p.name));const action=state.hired[b.id]?`Working here: ${state.hired[b.id]}`:job?`Assign ${job.name} to this shop`:'Invite a survivor to work here';openModal(`<div class="modal-kicker">YOUR SETTLEMENT · ${b.kind.toUpperCase()}</div><h2>${b.label}</h2><p class="modal-lead">A new place for neighbors to gather, trade, and make something good. You can move freely and build anywhere.</p><div class="option-card"><span class="option-symbol">${b.kind==='garden'?'❋':b.kind==='diner'?'☕':b.kind==='shop'?'▤':'⌂'}</span><div class="option-copy"><b>${b.kind==='shelter'?'A safe place to rest':'Open for business'}</b><p>${state.hired[b.id]?`${state.hired[b.id]} is keeping things running.`:b.kind==='shelter'?'Your shelter is a little home base.':'Assign any survivor to staff this place.'}</p></div><div class="option-meta">${state.hired[b.id]?'STAFFED':'YOURS'}</div></div>${b.kind!=='shelter'&&!state.hired[b.id]?actionButton(action,`assign-${b.id}`,!job):''}${state.hired[b.id]?'<div class="modal-note">Your worker earns 4 Grade every 30 seconds. Work a shift here yourself for an extra 20 Grade.</div>':''}${actionButton('WORK A SHIFT · +20 GRADE',`shift-${b.id}`,state.completed.includes('shift-'+b.id))}`);}
  function handleAction(action){
    if(action==='build'){openBuild();return;}if(action==='missions'){openMissions();return;}if(action==='people'){openPeople();return;}if(action==='jobs'){openJobs();return;}if(action==='trade'){openExchange();return;}
    if(action.startsWith('choose-')){const kind=action.slice(7);const option=buildOptions.find(o=>o.id===kind);if(!option||!canPay(option.cost))return;state.pendingBuild=kind;state.buildMode=true;closeModal();mapToast(`PLACE ${option.name.toUpperCase()} · TAP AN OPEN TILE`);draw();return;}
    if(action.startsWith('search-')){const id=action.slice(7),o=placeById(id);if(state.searched.includes(id))return;const loot=id==='crate'?{wood:2,metal:1,food:1}:id==='mill'?{metal:2,cloth:1,carParts:1}:{metal:1,wood:1,carParts:1};Object.entries(loot).forEach(([k,v])=>changeResource(k,v));state.searched.push(id);if(!state.visited)state.visited=[];if(!state.visited.includes(id)){state.visited.push(id);state.discoveries++;}syncUI();toast(`Found ${Object.entries(loot).map(([k,v])=>`${v} ${labels[k]}`).join(', ')}`,'⌕');openSalvage(o);return;}
    if(action.startsWith('recruit-')){const id=action.slice(8);const o=locations.find(l=>l.person?.id===id);if(!o||state.recruits.some(p=>p.id===id))return;state.recruits.push({...o.person});state.discoveries++;syncUI();toast(`${o.person.name} joined your settlement`,'◎');openPerson({...o,person:null});$('#modalContent').innerHTML=`<div class="modal-kicker">A GOOD DAY FOR NEW EDEN</div><h2>${o.person.name} is home.</h2><p class="modal-lead">${o.person.name.split(' ')[0]} is settling in. Build a shop anywhere and assign them to work there.</p><div class="person-row"><span class="person-avatar">${o.person.name[0]}</span><div><b>${o.person.name}</b><small>${o.person.role}</small></div><span class="person-status">SETTLED</span></div>${actionButton('MEET THE NEIGHBORHOOD','close')}`;return;}
    if(action.startsWith('buy-')){const id=action.slice(4),cost={wood:18,metal:22,cloth:14,food:10,carParts:38}[id];if(state.grade<cost)return;state.grade-=cost;changeResource(id,1);syncUI();toast(`Traded ${cost} Grade for ${labels[id]}`,'⇄');openExchange();return;}
    if(action.startsWith('sell-')){const id=action.slice(5);if(state[id]<1)return;changeResource(id,-1);state.grade+=id==='wood'?8:10;syncUI();toast(`Sold ${labels[id]} for Grade`,'G');openExchange();return;}
    if(action==='meal'){if(state.food<1)return;state.food--;state.grade+=5;syncUI();toast('A good meal and a little neighborhood gossip. +5 Grade','☕');closeModal();return;}
    if(action==='repair-car'){if(state.carParts<3||state.carFixed)return;state.carParts-=3;state.carFixed=true;state.completed.push('delivery');state.grade+=40;syncUI();toast('Sky-car repaired! Delivery mission complete · +40 Grade','✦');openGarage();return;}
    if(action==='car-mission'){if(state.completed.includes('delivery'))return;state.accepted.push('delivery');closeModal();mapToast('Visit Cloudline Garage to help repair the sky-car');return;}
    if(action==='gather-food'){if(state.completed.includes('garden-gather'))return;state.food+=2;state.completed.push('garden-gather');syncUI();toast('Gathered 2 fresh rations','❋');openGreenhouse(placeById('greenhouse'));return;}
    if(action==='welcome-mission'){if(state.completed.includes('welcome')||!canPay({wood:2,food:1}))return;pay({wood:2,food:1});state.completed.push('welcome');state.grade+=55;syncUI();toast('The family is safe in New Eden · +55 Grade','✧');openRelay();return;}
    if(action==='errands'){if(state.completed.includes('errands'))return;state.completed.push('errands');state.grade+=18;syncUI();toast('A shift well done · +18 Grade','G');openMissions();return;}
    if(action.startsWith('shift-')){const id=action.slice(6);if(state.completed.includes('shift-'+id))return;state.completed.push('shift-'+id);state.grade+=20;syncUI();toast('You worked a good shift · +20 Grade','G');openJobs();return;}
    if(action.startsWith('assign-')){const id=action.slice(7),b=state.buildings.find(x=>x.id===id);const job=state.recruits.find(p=>!Object.values(state.hired).includes(p.name));if(!b||!job)return;state.hired[id]=job.name;syncUI();toast(`${job.name} is working at ${b.label}`,'◎');openBuilt(b);return;}
    if(action==='close'){closeModal();return;}if(action.startsWith('go-')){const id=action.slice(3);closeModal();visitLocation(id);}
  }
  function placeBuilding(x,y){const kind=state.pendingBuild,o=buildOptions.find(b=>b.id===kind);if(!o)return;const occupied=[...locations.map(l=>key(l.x,l.y)),...state.buildings.map(b=>key(b.x,b.y))];if(occupied.includes(key(x,y))){mapToast('That spot is already in use. Try an open tile.');return;}if(!canPay(o.cost)){state.buildMode=false;mapToast('Not enough supplies yet.');openBuild();return;}pay(o.cost);const b={id:`build-${Date.now()}`,kind,label:o.name,x,y};state.buildings.push(b);state.pendingBuild=null;state.buildMode=false;state.player={x,y};syncUI();toast(`${o.name} built!`,'▦');mapToast('A new beginning, right where you want it.');}
  function mapClick(event){const r=canvas.getBoundingClientRect();const mx=event.clientX-r.left,my=event.clientY-r.top;let nearest=null,dist=Infinity;const all=[...locations,...state.buildings.map(b=>({...b,isBuilt:true}))];for(const o of all){const p=point(o.x,o.y);const d=Math.hypot((mx-p.x)/1.1,my-p.y);if(d<dist){dist=d;nearest=o;}}
    if(state.buildMode){const dx=(mx-W*.5-state.worldOffset.x)*2/tileW,dy=(my-H*.39-state.worldOffset.y)*2/tileH;let x=Math.round((dx+dy)/2),y=Math.round((dy-dx)/2);x=Math.max(0,Math.min(13,x));y=Math.max(0,Math.min(9,y));placeBuilding(x,y);return;}
    if(nearest&&dist<Math.max(tileW*.7,39)){state.player={x:nearest.x,y:nearest.y};draw();if(nearest.isBuilt)openBuilt(nearest);else openPlace(nearest);return;}
    const dx=(mx-W*.5-state.worldOffset.x)*2/tileW,dy=(my-H*.39-state.worldOffset.y)*2/tileH;const x=Math.round((dx+dy)/2),y=Math.round((dy-dx)/2);if(x>=0&&x<14&&y>=0&&y<10){state.player={x,y};draw();mapToast('A quiet corner of the neighborhood. Keep exploring.');}
  }
  function move(dx,dy){const x=Math.max(0,Math.min(13,state.player.x+dx)),y=Math.max(0,Math.min(9,state.player.y+dy));state.player={x,y};$('#coordLabel').textContent=`SECTOR ${String(x+1).padStart(2,'0')} · ${String(y+1).padStart(2,'0')}`;draw();}
  function setZoom(amount){state.zoom=Math.max(.78,Math.min(1.3,state.zoom+amount));resize();$('#zoomLabel').textContent=`${Math.round(state.zoom*100)}%`;}
  function tick(){const now=Date.now();if(now-state.lastTick>30000){const cycles=Math.floor((now-state.lastTick)/30000);const staffed=Object.keys(state.hired).length;if(staffed){state.grade+=staffed*4*cycles;toast(`Your shops earned ${staffed*4*cycles} Grade`,'G');}state.lastTick=now;syncUI();}}
  function init(){load();syncUI();resize();window.addEventListener('resize',resize);canvas.addEventListener('click',mapClick);$('#modalClose').addEventListener('click',closeModal);$('#modalBackdrop').addEventListener('click',e=>{if(e.target.id==='modalBackdrop')closeModal();});$('#modalContent').addEventListener('click',e=>{const b=e.target.closest('[data-do]');if(b&&!b.disabled)handleAction(b.dataset.do);});
    document.addEventListener('click',e=>{const tab=e.target.closest('[data-tab]');if(tab){document.querySelectorAll('.rail-link').forEach(x=>x.classList.toggle('active',x===tab));const t=tab.dataset.tab;if(t==='missions')openMissions();if(t==='people')openPeople();if(t==='build')openBuild();if(t==='overview')closeModal();}
      const quick=e.target.closest('[data-action]');if(quick){const a=quick.dataset.action;if(a==='scavenge'){const next=locations.find(o=>['crate','mill','junkyard'].includes(o.id)&&!state.searched.includes(o.id));if(next)visitLocation(next.id);else toast('You have searched every salvage spot. Check again tomorrow.','⌕');}else handleAction(a);}
      const sight=e.target.closest('.sighting');if(sight)visitLocation(sight.dataset.target);
    });
    $('#startBuildBtn').addEventListener('click',openBuild);$('#helpBtn').addEventListener('click',()=>openModal(`<div class="modal-kicker">WELCOME TO NEW EDEN</div><h2>Your world, your pace.</h2><p class="modal-lead">The year is 2442. The old world is quiet, the sky-cars are grounded, and people are finding each other again. There are no monsters here—just a world waiting to feel like home.</p><div class="help-grid"><div class="help-step"><b>⌕ Explore</b><p>Click a place on the map or use WASD / arrow keys to move. Search crates and old buildings for supplies.</p></div><div class="help-step"><b>◎ Find people</b><p>Survivors are tucked in shops, restaurants, and salvage sites. Invite them to join your settlement.</p></div><div class="help-step"><b>▦ Build anywhere</b><p>Use your supplies or trade Grade at the Corner Exchange. Choose a building and tap any open tile.</p></div><div class="help-step"><b>✧ Make a living</b><p>Work shifts, take missions, hire survivors for your shops, and find flight parts to repair your sky-car.</p></div></div><div class="modal-note">Your progress autosaves on this device. Tip: click the old supply crate near the center to get started.</div>`));
    $('#centerBtn').addEventListener('click',()=>{state.worldOffset={x:0,y:0};draw();});$('#zoomIn').addEventListener('click',()=>setZoom(.08));$('#zoomOut').addEventListener('click',()=>setZoom(-.08));$('#mapHelp').addEventListener('click',()=>toast('Dotted spots are supplies · rust colored figures are survivors · build anywhere on open land','⌖'));$('#soundBtn').addEventListener('click',()=>{state.muted=!state.muted;$('#soundBtn').textContent=state.muted?'♪':'♫';toast(state.muted?'Ambience off':'Ambience on','♫');});
    document.addEventListener('keydown',e=>{if(['INPUT','TEXTAREA'].includes(document.activeElement.tagName))return;if(e.key==='Escape'){closeModal();return;}if($('#modalBackdrop').classList.contains('open'))return;const k=e.key.toLowerCase();if(k==='w'||k==='arrowup')move(0,-1);if(k==='s'||k==='arrowdown')move(0,1);if(k==='a'||k==='arrowleft')move(-1,0);if(k==='d'||k==='arrowright')move(1,0);});setInterval(tick,5000);
    setTimeout(()=>{if(!localStorage.getItem('afterlight-intro')){localStorage.setItem('afterlight-intro','seen');openModal(`<div class="modal-kicker">NEW EDEN · YEAR 2442</div><h2>There is room to begin again.</h2><p class="modal-lead">The old world is quiet. The people you find are not. Gather a few supplies, meet your neighbors, and make this place your own.</p><div class="option-card"><span class="option-symbol">✳</span><div class="option-copy"><b>A softer frontier</b><p>Explore, build, trade, and help each other. No monsters. No rush.</p></div></div><div class="modal-note">Start by searching the supply crate at the center of the map. Your progress saves automatically.</div><button class="modal-action" data-do="close">LET'S BEGIN ↗</button>`);}},450);
  }
  init();
})();

