   function handleAction(action){
     if(action==='build'){openBuild();return;}if(action==='missions'){openMissions();return;}if(action==='people'){openPeople();return;}if(action==='jobs'){openJobs();return;}if(action==='trade'){openExchange();return;}
     if(action.startsWith('choose-')){const kind=action.slice(7);const option=buildOptions.find(o=>o.id===kind);if(!option||!canPay(option.cost))return;state.pendingBuild=kind;state.buildMode=true;closeModal();mapToast(`PLACE ${option.name.toUpperCase()} · TAP AN OPEN TILE`);draw();return;}
     if(action.startsWith('search-')){const id=action.slice(7),o=placeById(id);if(state.searched.includes(id))return;const loot=id==='crate'?{wood:2,metal:1,food:1}:id==='mill'?{metal:2,cloth:1,carParts:1}:{metal:1,wood:1,carParts:1};Object.entries(loot).forEach(([k,v])=>changeResource(k,v));state.searched.push(id);if(!state.visited)state.visited=[];if(!state.visited.includes(id)){state.visited.push(id);state.discoveries++;}syncUI();toast(`Found ${Object.entries(loot).map(([k,v])=>`${v} ${labels[k]}`).join(', ')}`,'⌕');openSalvage(o);return;}
-    if(action.startsWith('recruit-')){const id=action.slice(8);const o=locations.find(l=>l.person?.id===id);if(!o||state.recruits.some(p=>p.id===id))return;state.recruits.push({...o.person});state.discoveries++;syncUI();toast(`${o.person.name} joined your settlement`,'◎');openPerson({...o,person:null});$('#modalContent').innerHTML=`<div class="modal-kicker">A GOOD DAY FOR NEW EDEN</div><h2>${o.person.name} is home.</h2><p class="modal-lead">${o.person.name.split(' ')[0]} is settling in. Build a shop anywhere and assign them to work there.</p><div class="person-row"><span class="person-avatar">${o.person.name[0]}</span><div><b>${o.person.name}</b><small>${o.person.role}</small></div><span class="person-status">SETTLED</span></div>${actionButton('MEET THE NEIGHBORHOOD','close')}`;return;}
+    if(action.startsWith('recruit-')){const id=action.slice(8);const o=locations.find(l=>l.person?.id===id);if(!o||state.recruits.some(p=>p.id===id))return;state.recruits.push({...o.person});state.discoveries++;syncUI();toast(`${o.person.name} joined your settlement`,'◎');$('#modalContent').innerHTML=`<div class="modal-kicker">A GOOD DAY FOR NEW EDEN</div><h2>${o.person.name} is home.</h2><p class="modal-lead">${o.person.name.split(' ')[0]} is settling in. Build a shop anywhere and assign them to work there.</p><div class="person-row"><span class="person-avatar">${o.person.name[0]}</span><div><b>${o.person.name}</b><small>${o.person.role}</small></div><span class="person-status">SETTLED</span></div>${actionButton('MEET THE NEIGHBORHOOD','close')}`;return;}
     if(action.startsWith('buy-')){const id=action.slice(4),cost={wood:18,metal:22,cloth:14,food:10,carParts:38}[id];if(state.grade<cost)return;state.grade-=cost;changeResource(id,1);syncUI();toast(`Traded ${cost} Grade for ${labels[id]}`,'⇄');openExchange();return;}
     if(action.startsWith('sell-')){const id=action.slice(5);if(state[id]<1)return;changeResource(id,-1);state.grade+=id==='wood'?8:10;syncUI();toast(`Sold ${labels[id]} for Grade`,'G');openExchange();return;}
     if(action==='meal'){if(state.food<1)return;state.food--;state.grade+=5;syncUI();toast('A good meal and a little neighborhood gossip. +5 Grade','☕');closeModal();return;}
     if(action==='repair-car'){if(state.carParts<3||state.carFixed)return;state.carParts-=3;state.carFixed=true;state.completed.push('delivery');state.grade+=40;syncUI();toast('Sky-car repaired! Delivery mission complete · +40 Grade','✦');openGarage();return;}

